beginning.embedded_functions:
#include <arpa/inet.h>

// Returns 1 when the address of a PORT "h1,h2,h3,h4,p1,p2" or EPRT "|1|a.b.c.d|port|" argument
// is a valid IPv4 address different from #ip_src (4 bytes, network order); 0 otherwise.
static inline int em_ftp_port_addr_differs( const char *cmd, const char *param, const void *ip_src ){
	unsigned int h[4];
	char addr[16];
	struct in_addr given;
	if( cmd == NULL || param == NULL || ip_src == NULL )
		return 0;
	if( strncasecmp( cmd, "PORT", 4 ) == 0 ){
		if( sscanf( param, " %u,%u,%u,%u,", &h[0], &h[1], &h[2], &h[3] ) != 4 )
			return 0;
		if( h[0] > 255 || h[1] > 255 || h[2] > 255 || h[3] > 255 )
			return 0;
		given.s_addr = htonl( (h[0] << 24) | (h[1] << 16) | (h[2] << 8) | h[3] );
	}else if( strncasecmp( cmd, "EPRT", 4 ) == 0 ){
		// EPRT |1|a.b.c.d|port| (RFC 2428); only IPv4 (protocol 1) is compared
		if( sscanf( param, " |1|%15[0-9.]|", addr ) != 1 || inet_pton( AF_INET, addr, &given ) != 1 )
			return 0;
	}else
		return 0;
	return memcmp( &given.s_addr, ip_src, 4 ) != 0;
}
